  for (const item of completedResults) {
    try {
      const completeResult = await helpers.httpRequest({
        method: 'POST',
        url: 'http://mock-api:8000/warehouse/inventory-sync-jobs/' + encodeURIComponent(item.job_id) + '/complete',
        body: { processed_by: 'warehouse-agent', result: item.sync || syncJobsResult },
        json: true
      });
      completed.push({ ...item, job: completeResult.job });
    } catch (completeError) {
      const message = 'warehouse_inventory_sync_complete_failed: ' + errorMessage(completeError);
      try {
        await helpers.httpRequest({
          method: 'POST',
          url: 'http://mock-api:8000/warehouse/inventory-sync-jobs/' + encodeURIComponent(item.job_id) + '/fail',
          body: { processed_by: 'warehouse-agent', error: message },
          json: true
        });
      } catch (failError) {}
      failed.push({ ...item, error: message });
    }
  }

  for (const item of failedResults) {
    const message = item.error || syncJobsResult.message || syncJobsResult.error || 'warehouse_inventory_sync_failed';
    try {
      await helpers.httpRequest({
        method: 'POST',
        url: 'http://mock-api:8000/warehouse/inventory-sync-jobs/' + encodeURIComponent(item.job_id) + '/fail',
        body: { processed_by: 'warehouse-agent', error: message },
        json: true
      });
    } catch (failError) {}
    failed.push({ ...item, error: message });
  }

  return JSON.stringify({
    ok: failed.length === 0 && syncJobsResult.ok === true,
