    completed_count: completed.length,
    failed_count: failed.length,
    completed,
    failed,
    sync_result: syncJobsResult,
    pending_count_before: pending.count || 0
  });
} catch (error) {
  return JSON.stringify({
    ok: false,
    error: 'warehouse_inventory_sync_jobs_runtime_error',
