function parseMaybeJson(value) {
  if (typeof value !== 'string') return value || {};
  const trimmed = value.trim();
  try { return JSON.parse(trimmed); } catch (error) { return { query: trimmed }; }
}
function first(...values) { return values.find((value) => value !== undefined && value !== null && String(value).trim() !== ''); }
function extractText(input) { return String(first(input.query, input.text, input.input, '')).trim(); }
function extractAction(input, text) {
  const explicit = String(first(input.action, input.operation, '')).trim().toLowerCase();
  if (explicit) return explicit;
  if (/退货|return/i.test(text)) return 'return';
  if (/取消|退款|cancel|refund/i.test(text)) return 'cancel';
  if (/确认发仓|确认仓库|confirm_fulfillment|confirm warehouse/i.test(text)) return 'confirm_fulfillment';
  if (/到货|签收|arrive|delivered/i.test(text)) return 'arrive';
  if (/发货|ship/i.test(text)) return 'ship';
  if (/付款|支付|pay|paid/i.test(text) && /创建|下单|create/i.test(text)) return 'create_and_pay';
  if (/付款|支付|pay|paid/i.test(text)) return 'pay';
  if (/创建|下单|create/i.test(text)) return 'create';
  return '';
}
function extractOrderId(input, text) {
  const explicit = String(first(input.order_id, input.orderId, '')).trim();
  if (explicit) return explicit;
  const match = text.match(/\bORD-[0-9A-Za-z_-]+\b/i);
  return match ? match[0].toUpperCase() : '';
}
function extractItemId(input, text) {
  const explicit = String(first(input.item_id, input.itemId, '')).trim();
  if (explicit) return explicit;
  const match = text.match(/\bitem_[0-9A-Za-z_]+\b/i);
  return match ? match[0].toLowerCase() : '';
}
function extractWarehouseId(input, text) {
  const explicit = String(first(input.warehouse_id, input.warehouseId, '')).trim();
  if (explicit) return explicit;
  const match = text.match(/\bwh_[0-9A-Za-z_]+\b/i);
  return match ? match[0].toLowerCase() : '';
}
function extractDeliveryProviderId(input, text) {
  const explicit = String(first(input.delivery_provider_id, input.deliveryProviderId, input.carrier, '')).trim();
  if (explicit) return explicit.toLowerCase();
  const match = text.match(/(?:物流|快递|carrier)\s*([a-z]{2,8})/i);
  return match ? match[1].toLowerCase() : '';
}
function extractShippingAddress(input, text) {
  const explicit = String(first(input.shipping_address, input.shippingAddress, '')).trim();
  if (explicit) return explicit;
  const match = text.match(/[\u4e00-\u9fa5]+省[\u4e00-\u9fa5]+市/);
  return match ? match[0] : '';
}
function extractQuantity(input, text) {
  const explicit = Number(first(input.quantity, input.qty, ''));
  if (Number.isFinite(explicit) && explicit > 0) return explicit;
  const matches = Array.from(text.matchAll(/(\d+)\s*(?:件|个|箱|瓶|包)?/g));
  return matches.length ? Number(matches[matches.length - 1][1]) : 1;
}
function normalizeItems(input, text) {
  if (Array.isArray(input.items) && input.items.length > 0) {
    return input.items.map((item) => ({
      item_id: String(first(item.item_id, item.itemId, '')).trim(),
      warehouse_id: String(first(item.warehouse_id, item.warehouseId, '')).trim(),
      location_code: String(first(item.location_code, item.locationCode, '')).trim(),
      quantity: Number(first(item.quantity, item.qty, 1))
    }));
  }
  const itemId = extractItemId(input, text);
  if (!itemId) return [];
  return [{ item_id: itemId, warehouse_id: extractWarehouseId(input, text), location_code: String(first(input.location_code, input.locationCode, '')).trim(), quantity: extractQuantity(input, text) }];
}
